update public.project_sections set body = $dari${"en":"No live payment provider yet: HesabPay (the target gateway) integration is blocked on getting developer/sandbox credentials from the provider — an external dependency outside my control, not a technical gap.","fa":"هنوز درگاه پرداخت زنده وصل نیست. اتصال حساب‌پی به دریافت دسترسی developer/sandbox از خودِ ارائه‌دهنده وابسته است؛ این یک وابسته‌گی بیرونی است، نه یک نقص فنی در سیستم."}$dari$::jsonb where id = '2e94becd-b278-4d18-a03e-2044fcbc024b' and body = $dari${"en":"No live payment provider yet: HesabPay (the target gateway) integration is blocked on getting developer/sandbox credentials from the provider — an external dependency outside my control, not a technical gap.","fa":"هنوز درگاه پرداخت زنده وصل نیست. اتصال حساب‌پی به دریافت دسترسی developer/sandbox از خودِ ارائه‌دهنده وابسته است؛ این یک وابستگی بیرونی است، نه یک نقص فنی در سامانه."}$dari$::jsonb;
update public.project_sections set body = $dari${"en":"A bilingual Dari/English portal I built for Pezhohesh Complex, an educational institute I run myself — a study lounge, academic advising, scholarship listings and student achievements, all manageable by non-developer staff through a custom admin panel.","fa":"پورتالی دوزبانه برای مجتمع پژوهش ساختم؛ مؤسسه‌ای آموزشی که خودم اداره‌اش می‌کنم. سالن مطالعه، مشوره‌ی تحصیلی، بورسیه‌های فعال و دستاوردهای محصلان از طریق یک پنل ادمین اختصاصی مدیریت می‌شوند."}$dari$::jsonb where id = '6567f2ea-6663-4dfa-b144-1cd9f24146b0' and body = $dari${"en":"A bilingual Dari/English portal I built for Pezhohesh Complex, an educational institute I run myself — a study lounge, academic advising, scholarship listings and student achievements, all manageable by non-developer staff through a custom admin panel.","fa":"پورتالی دوزبانه برای مجتمع پژوهش ساختم؛ مؤسسه‌ای آموزشی که خودم اداره‌اش می‌کنم. سالن مطالعه، مشاوره‌ی تحصیلی، بورسیه‌های فعال و دستاوردهای دانشجویی از طریق یک پنل ادمین اختصاصی مدیریت می‌شوند."}$dari$::jsonb;
update public.project_sections set body = $dari${"en":"Next.js (App Router) talks to PostgreSQL through Supabase for both the passenger app and the operations admin. Supabase Auth handles sessions; every privileged read or write additionally passes through PostgreSQL Row-Level Security plus explicit server-side authorization checks — a service-role client is never treated as an authorization decision by itself. Seat availability follows a strict state machine (available → held → booked, with holds expiring back to available), and payment status follows its own database-enforced state machine. The browser only ever displays state; it never originates it.","fa":"Next.js (App Router) برای مسیر مسافر و پنل عملیات از طریق Supabase به PostgreSQL متصل می‌شود. Supabase Auth نشست‌ها را مدیریت می‌کند.\n\nعملیات حساس علاوه بر RLS از بررسی دسترسی سمت سرور هم عبور می‌کنند. کلاینت service-role به‌تنهایی مجوز دسترسی محسوب نمی‌شود.\n\nوضعیت چوکی و پرداخت نیز هرکدام state machine مشخص خودشان را دارند. مرورگر فقط وضعیت را نمایش می‌دهد."}$dari$::jsonb where id = '40f48c7c-b072-441d-8d16-75caba9025f7' and body = $dari${"en":"Next.js (App Router) talks to PostgreSQL through Supabase for both the passenger app and the operations admin. Supabase Auth handles sessions; every privileged read or write additionally passes through PostgreSQL Row-Level Security plus explicit server-side authorization checks — a service-role client is never treated as an authorization decision by itself. Seat availability follows a strict state machine (available → held → booked, with holds expiring back to available), and payment status follows its own database-enforced state machine. The browser only ever displays state; it never originates it.","fa":"Next.js (App Router) برای مسیر مسافر و پنل عملیات از طریق Supabase به PostgreSQL متصل می‌شود. Supabase Auth نشست‌ها را مدیریت می‌کند.\n\nعملیات حساس علاوه بر RLS از بررسی دسترسی سمت سرور هم عبور می‌کنند. کلاینت service-role به‌تنهایی مجوز دسترسی محسوب نمی‌شود.\n\nوضعیت صندلی و پرداخت نیز هرکدام state machine مشخص خودشان را دارند. مرورگر فقط وضعیت را نمایش می‌دهد."}$dari$::jsonb;
update public.project_sections set body = $dari${"en":"A booking and operations platform built for intercity bus companies in Afghanistan. The market runs on manual ticket counters and phone-based booking, with no shared system connecting passenger sales to fleet and trip operations. I built this as a real product bet: passengers get a live seat map and a bookable trip search, and operators get a database-backed admin for routes, fleet, drivers, trips and reporting — the two sides of the same booking, in one system.","fa":"این سیستم برای فروش تکت و مدیریت عملیات شرکت‌های ترانسپورتی بین‌شهری در افغانستان ساخته شده است. این بازار هنوز عمدتاً با گیشه‌های فروش دستی و فروش تلفنی تکت اداره می‌شود و سیستم مشترکی برای اتصال فروش تکت به عملیات موترها و سفرها وجود ندارد.\n\nمسافران سفر را جست‌وجو و چوکی را روی نقشه‌ی زنده انتخاب می‌کنند. اپراتورها هم مسیرها، موترها، رانندگان و سفرها را از یک پنل متصل به پایگاه داده مدیریت می‌کنند."}$dari$::jsonb where id = 'c88689bb-912a-4a79-8dad-1c99e2ee9b26' and body = $dari${"en":"A booking and operations platform built for intercity bus companies in Afghanistan. The market runs on manual ticket counters and phone-based booking, with no shared system connecting passenger sales to fleet and trip operations. I built this as a real product bet: passengers get a live seat map and a bookable trip search, and operators get a database-backed admin for routes, fleet, drivers, trips and reporting — the two sides of the same booking, in one system.","fa":"این سامانه برای رزرو و مدیریت عملیات شرکت‌های اتوبوس‌رانی بین‌شهری در افغانستان ساخته شده است. این بازار هنوز عمدتاً با گیشه‌های فروش دستی و رزرو تلفنی اداره می‌شود و سامانه‌ی مشترکی برای اتصال فروش بلیت به عملیات ناوگان و سفرها وجود ندارد.\n\nمسافران سفر را جست‌وجو و صندلی را روی نقشه‌ی زنده انتخاب می‌کنند. اپراتورها هم مسیرها، ناوگان، رانندگان و سفرها را از یک پنل متصل به پایگاه داده مدیریت می‌کنند."}$dari$::jsonb;
update public.project_sections set body = $dari${"en":"Built with five responsive tiers from mobile (under 768px) through ultra-wide (2560px and up), covering both the passenger booking flow and the admin's wide data tables. RTL/LTR behaviour is treated as a layout requirement from the start (Dari/English), not a late pass — including RTL-aware admin navigation and wide-table handling.","fa":"رابط در پنج بازه‌ی واکنش‌گرا از موبایل تا نمایشگرهای فوق‌عریض کار می‌کند؛ هم برای خرید تکت مسافر و هم جدول‌های عریض پنل ادمین. RTL/LTR نیز از ابتدا بخشی از طراحی بوده و فقط در پایان اضافه نشده است."}$dari$::jsonb where id = '8868b28c-8f16-4732-bdfe-8536cc4262f9' and body = $dari${"en":"Built with five responsive tiers from mobile (under 768px) through ultra-wide (2560px and up), covering both the passenger booking flow and the admin's wide data tables. RTL/LTR behaviour is treated as a layout requirement from the start (Dari/English), not a late pass — including RTL-aware admin navigation and wide-table handling.","fa":"رابط در پنج بازه‌ی واکنش‌گرا از موبایل تا نمایشگرهای فوق‌عریض کار می‌کند؛ هم برای رزرو مسافر و هم جدول‌های عریض پنل ادمین. RTL/LTR نیز از ابتدا بخشی از طراحی بوده و فقط در پایان اضافه نشده است."}$dari$::jsonb;
update public.project_sections set body = $dari${"en":"Finished: passenger booking with server-enforced seat holds, operations admin (routes, fleet, drivers, trips, bookings, reports, CSV), loyalty and coupon foundations, a public CMS lite with in-site responsive image cropping, and a full payment-status state machine with audit trail and partial refunds — all running on manual/offline payment confirmation. Not finished: a live payment gateway. HesabPay integration is the next planned step and is blocked on getting developer/sandbox credentials from the provider — until that's resolved, online bookings are recorded but stay in a pending payment state rather than auto-confirming.","fa":"انجام‌شده: خرید تکت مسافر با hold چوکی سمت سرور، پنل عملیات برای مسیرها، موترها، رانندگان، سفرها، تکت‌ها، گزارش‌ها و CSV، پایه‌های loyalty و کوپن، CMS عمومی سبک و state machine کامل پرداخت همراه با audit و بازپرداخت جزئی. پرداخت‌ها هنوز تأیید خودکار ندارند؛ اتصال حساب‌پی به دریافت دسترسی developer/sandbox از ارائه‌دهنده وابسته است."}$dari$::jsonb where id = 'ba0853d2-ca5a-40fc-909c-48e854e5abe2' and body = $dari${"en":"Finished: passenger booking with server-enforced seat holds, operations admin (routes, fleet, drivers, trips, bookings, reports, CSV), loyalty and coupon foundations, a public CMS lite with in-site responsive image cropping, and a full payment-status state machine with audit trail and partial refunds — all running on manual/offline payment confirmation. Not finished: a live payment gateway. HesabPay integration is the next planned step and is blocked on getting developer/sandbox credentials from the provider — until that's resolved, online bookings are recorded but stay in a pending payment state rather than auto-confirming.","fa":"انجام‌شده: رزرو مسافر با hold صندلی سمت سرور، پنل عملیات برای مسیرها، ناوگان، رانندگان، سفرها، رزروها، گزارش‌ها و CSV، پایه‌های loyalty و کوپن، CMS عمومی سبک و state machine کامل پرداخت همراه با audit و بازپرداخت جزئی. پرداخت‌ها هنوز تأیید خودکار ندارند؛ اتصال حساب‌پی به دریافت دسترسی developer/sandbox از ارائه‌دهنده وابسته است."}$dari$::jsonb;
update public.project_sections set body = $dari${"en":"The core problem: seat availability and payment status are business-critical state that a booking site cannot let the browser decide. If two people can claim the same seat, or a cancelled booking can silently keep its payment marked as taken, the platform is unusable for a real operator. The goal was a passenger booking flow and an operations admin where every sensitive decision — holding a seat, confirming a booking, changing a payment's status — is made and enforced by the database, not the UI.","fa":"وضعیت چوکی و پرداخت داده‌های حیاتی این سیستم‌اند و نباید مرورگر درباره‌ی آن‌ها تصمیم بگیرد.\n\nاگر دو نفر یک چوکی را هم‌زمان بگیرند یا پرداخت یک تکت لغوشده همچنان دریافت‌شده بماند، سیستم قابل‌اعتماد نیست. برای همین، تصمیم‌های حساس فروش تکت، تأیید و پرداخت در پایگاه داده و سمت سرور اجرا می‌شوند."}$dari$::jsonb where id = '41b975c8-cac1-4419-8257-cd451c4810ed' and body = $dari${"en":"The core problem: seat availability and payment status are business-critical state that a booking site cannot let the browser decide. If two people can claim the same seat, or a cancelled booking can silently keep its payment marked as taken, the platform is unusable for a real operator. The goal was a passenger booking flow and an operations admin where every sensitive decision — holding a seat, confirming a booking, changing a payment's status — is made and enforced by the database, not the UI.","fa":"وضعیت صندلی و پرداخت داده‌های حیاتی این سامانه‌اند و نباید مرورگر درباره‌ی آن‌ها تصمیم بگیرد.\n\nاگر دو نفر یک صندلی را هم‌زمان بگیرند یا پرداخت یک رزرو لغوشده همچنان دریافت‌شده بماند، سیستم قابل‌اعتماد نیست. برای همین، تصمیم‌های حساس رزرو، تأیید و پرداخت در پایگاه داده و سمت سرور اجرا می‌شوند."}$dari$::jsonb;
update public.project_sections set body = $dari${"en":"While building the refund path, a security review with Supabase's advisory tooling turned up a real gap: the function that writes to the payment audit-trail table was callable directly by any authenticated (or even anonymous) client, with no permission check of its own — because it was only ever meant to be called internally, from inside other trusted functions. That meant anyone could have written fake entries into the audit history and undermined the one table meant to make payment changes reviewable. I revoked execute permission on that function from every role except its owner, then re-verified with a direct privilege check — not just the advisory tool — that only trusted internal callers could reach it. The same review also caught a real functional bug: an admin could \"cancel\" a booking whose payment was already confirmed, leaving the booking cancelled but the payment still marked as taken — money in, booking gone. I closed that path with an explicit error and routed it through the new refund function instead, so a paid booking can only be unwound by actually refunding it.","fa":"در مسیر ساخت بازپرداخت، بررسی امنیتی Supabase یک نقص دسترسی واقعی پیدا کرد: تابع ثبت تاریخچه‌ی پرداخت برای کلاینت‌های احراز‌هویت‌شده و حتی مهمان قابل‌فراخوانی بود. دسترسی اجرا محدود شد و دوباره با یک بررسی مستقیم تأیید شد.\n\nهمان بررسی یک مشکل دیگر را هم نشان داد: ادمین می‌توانست تکتی با پرداخت تأییدشده را لغو کند و پرداخت همچنان دریافت‌شده بماند. این مسیر بسته شد. حالا چنین تکتی فقط با بازپرداخت واقعی قابل لغو است."}$dari$::jsonb where id = '6467e179-148a-445b-a5bd-10171a4e5171' and body = $dari${"en":"While building the refund path, a security review with Supabase's advisory tooling turned up a real gap: the function that writes to the payment audit-trail table was callable directly by any authenticated (or even anonymous) client, with no permission check of its own — because it was only ever meant to be called internally, from inside other trusted functions. That meant anyone could have written fake entries into the audit history and undermined the one table meant to make payment changes reviewable. I revoked execute permission on that function from every role except its owner, then re-verified with a direct privilege check — not just the advisory tool — that only trusted internal callers could reach it. The same review also caught a real functional bug: an admin could \"cancel\" a booking whose payment was already confirmed, leaving the booking cancelled but the payment still marked as taken — money in, booking gone. I closed that path with an explicit error and routed it through the new refund function instead, so a paid booking can only be unwound by actually refunding it.","fa":"در مسیر ساخت بازپرداخت، بررسی امنیتی Supabase یک نقص دسترسی واقعی پیدا کرد: تابع ثبت تاریخچه‌ی پرداخت برای کلاینت‌های احراز‌هویت‌شده و حتی مهمان قابل‌فراخوانی بود. دسترسی اجرا محدود شد و دوباره با یک بررسی مستقیم تأیید شد.\n\nهمان بررسی یک مشکل دیگر را هم نشان داد: ادمین می‌توانست رزروی با پرداخت تأییدشده را لغو کند و پرداخت همچنان دریافت‌شده بماند. این مسیر بسته شد. حالا چنین رزروی فقط با بازپرداخت واقعی قابل لغو است."}$dari$::jsonb;
update public.project_sections set body = $dari${"en":"The institute needed a real content pipeline, not a static site someone has to ask a developer to update. Staff needed to publish scholarships, edit study-lounge rules, and review membership/advising requests themselves — with two different levels of access, since not everyone should be able to touch every part of the site. On top of that, visitors on unreliable connections needed pages they'd already seen to keep working, without the admin panel ever risking a stale view of pending requests.","fa":"مؤسسه به یک content pipeline واقعی نیاز داشت، نه سایتی که برای هر تغییر به توسعه‌دهنده وابسته باشد. کارکنان باید می‌توانستند بورسیه منتشر کنند، قوانین سالن مطالعه را ویرایش کنند و درخواست‌های عضویت و مشوره را بررسی کنند.\n\nبازدیدکننده با انترنت ناپایدار هم باید صفحات قبلی را می‌دید. در عین حال، پنل ادمین نباید داده‌ی قدیمیِ درخواست‌های در انتظار را نشان دهد."}$dari$::jsonb where id = '0a129c79-0ffc-42e6-9587-86eb95b63a03' and body = $dari${"en":"The institute needed a real content pipeline, not a static site someone has to ask a developer to update. Staff needed to publish scholarships, edit study-lounge rules, and review membership/advising requests themselves — with two different levels of access, since not everyone should be able to touch every part of the site. On top of that, visitors on unreliable connections needed pages they'd already seen to keep working, without the admin panel ever risking a stale view of pending requests.","fa":"مؤسسه به یک content pipeline واقعی نیاز داشت، نه سایتی که برای هر تغییر به توسعه‌دهنده وابسته باشد. کارکنان باید می‌توانستند بورسیه منتشر کنند، قوانین سالن مطالعه را ویرایش کنند و درخواست‌های عضویت و مشاوره را بررسی کنند.\n\nبازدیدکننده با اینترنت ناپایدار هم باید صفحات قبلی را می‌دید. در عین حال، پنل ادمین نباید داده‌ی قدیمیِ درخواست‌های در انتظار را نشان دهد."}$dari$::jsonb;
update public.project_sections set body = $dari${"en":"Deployed by building locally and uploading the production bundle directly, not a Git-triggered CI/CD pipeline — a deliberate simplicity trade-off for a small, single-maintainer project.","fa":"استقرار با build محلی و آپلود مستقیم خروجی انجام می‌شود. این انتخاب برای ساده‌گی یک پروژه‌ی کوچک با یک نگهدارنده است؛ CI/CD متصل به Git در این پروژه وجود ندارد."}$dari$::jsonb where id = '93c0ef3b-b4da-4744-9ab9-3c4dc905f58a' and body = $dari${"en":"Deployed by building locally and uploading the production bundle directly, not a Git-triggered CI/CD pipeline — a deliberate simplicity trade-off for a small, single-maintainer project.","fa":"استقرار با build محلی و آپلود مستقیم خروجی انجام می‌شود. این انتخاب برای سادگی یک پروژه‌ی کوچک با یک نگهدارنده است؛ CI/CD متصل به Git در این پروژه وجود ندارد."}$dari$::jsonb;
update public.project_sections set body = $dari${"context":{"en":"Partial refunds needed to release any coupon used on the booking, but wallet balance was also in scope for \"what should a refund touch.\"","fa":"بازپرداخت جزئی باید کوپن استفاده‌شده روی تکت را آزاد می‌کرد، ولی موجودی wallet هم در محدوده‌ی «بازپرداخت باید چه چیزهایی را برگرداند» بود."},"decision":{"en":"Checked real data before writing any logic — every existing booking had a zero wallet deduction, because wallet debiting was never wired into the booking-confirmation path in the first place. Built coupon release only; left wallet refund logic undone rather than building a return path for money that was never actually taken.","fa":"قبل از نوشتن منطق جدید، داده‌ی واقعی را بررسی کردم. هیچ تکتی کسر واقعی از wallet نداشت؛ این بخش اصلاً در مسیر تأیید تکت وصل نشده بود. بنابراین فقط آزادسازی کوپن را پیاده کردم و مسیر بازگشت wallet را تا زمانی که واقعاً کسر شود باز نگه داشتم."},"tradeoff":{"en":"The refund feature is incomplete until wallet debiting ships — documented as open debt rather than papered over with unused code.","fa":"مسیر بازپرداخت تا وقتی کسر wallet پیاده نشود کامل نیست. این مورد به‌عنوان بدهی فنی ثبت شده، نه اینکه با کد بی‌استفاده پوشانده شود."}}$dari$::jsonb where id = 'de176a06-26c4-49c5-ad0e-cc7dee2bc70a' and body = $dari${"context":{"en":"Partial refunds needed to release any coupon used on the booking, but wallet balance was also in scope for \"what should a refund touch.\"","fa":"بازپرداخت جزئی باید کوپن استفاده‌شده روی رزرو را آزاد می‌کرد، ولی موجودی wallet هم در محدوده‌ی «بازپرداخت باید چه چیزهایی را برگرداند» بود."},"decision":{"en":"Checked real data before writing any logic — every existing booking had a zero wallet deduction, because wallet debiting was never wired into the booking-confirmation path in the first place. Built coupon release only; left wallet refund logic undone rather than building a return path for money that was never actually taken.","fa":"قبل از نوشتن منطق جدید، داده‌ی واقعی را بررسی کردم. هیچ رزروی کسر واقعی از wallet نداشت؛ این بخش اصلاً در مسیر تأیید رزرو وصل نشده بود. بنابراین فقط آزادسازی کوپن را پیاده کردم و مسیر بازگشت wallet را تا زمانی که واقعاً کسر شود باز نگه داشتم."},"tradeoff":{"en":"The refund feature is incomplete until wallet debiting ships — documented as open debt rather than papered over with unused code.","fa":"مسیر بازپرداخت تا وقتی کسر wallet پیاده نشود کامل نیست. این مورد به‌عنوان بدهی فنی ثبت شده، نه اینکه با کد بی‌استفاده پوشانده شود."}}$dari$::jsonb;
update public.projects set summary = $dari${"en":"A bilingual Dari and English portal for a student community — study lounge, academic advising, scholarships and achievements — run through a custom CMS that non-developers can manage safely.","fa":"پورتالی دوزبانه برای یک جامعه‌ی محصلان با بخش‌های سالن مطالعه، مشوره‌ی تحصیلی، بورسیه و دستاوردها که از طریق یک CMS اختصاصی توسط کارکنان غیرتوسعه‌دهنده هم قابل مدیریت است."}$dari$::jsonb where id = '9bb1d3a5-cbbc-4f72-8dc9-e2ee0fba75bd' and summary = $dari${"en":"A bilingual Dari and English portal for a student community — study lounge, academic advising, scholarships and achievements — run through a custom CMS that non-developers can manage safely.","fa":"پورتالی دوزبانه برای یک جامعه‌ی دانشجویی با بخش‌های سالن مطالعه، مشاوره‌ی تحصیلی، بورسیه و دستاوردها که از طریق یک CMS اختصاصی توسط کارکنان غیرتوسعه‌دهنده هم قابل مدیریت است."}$dari$::jsonb;
update public.projects set highlights = $dari$[{"en":"Seat holds and booking confirmation are enforced on the server, never in the browser","fa":"نگه‌داشت موقت چوکی و تأیید نهایی در سمت سرور انجام می‌شود، نه در مرورگر"},{"en":"Operations admin for routes, fleet, trips, bookings, reports and CSV exports","fa":"پنل عملیات برای مسیرها، موترها، سفرها، تکت‌ها، گزارش‌ها و خروجی CSV"},{"en":"PostgreSQL row-level security combined with server-side authorization checks","fa":"استفاده از Row-Level Security در PostgreSQL همراه با بررسی دسترسی در سمت سرور"}]$dari$::jsonb where id = '7ef73c47-5d3e-4d2c-be2f-6fd48e08706b' and highlights = $dari$[{"en":"Seat holds and booking confirmation are enforced on the server, never in the browser","fa":"نگه‌داشت موقت صندلی و تأیید نهایی در سمت سرور انجام می‌شود، نه در مرورگر"},{"en":"Operations admin for routes, fleet, trips, bookings, reports and CSV exports","fa":"پنل عملیات برای مسیرها، ناوگان، سفرها، رزروها، گزارش‌ها و خروجی CSV"},{"en":"PostgreSQL row-level security combined with server-side authorization checks","fa":"استفاده از Row-Level Security در PostgreSQL همراه با بررسی دسترسی در سمت سرور"}]$dari$::jsonb;
update public.projects set summary = $dari${"en":"A booking and operations platform for intercity bus companies: passengers search trips and pick seats on a live seat map, while operators manage routes, buses, drivers and trips from a database-backed admin.","fa":"پلتفرم فروش تکت و مدیریت عملیات برای شرکت‌های ترانسپورتی بین‌شهری است. مسافران سفر را جست‌وجو و چوکی را روی نقشه‌ی زنده انتخاب می‌کنند؛ اپراتورها هم مسیرها، موترها، رانندگان و سفرها را از یک پنل متصل به پایگاه داده مدیریت می‌کنند."}$dari$::jsonb where id = '7ef73c47-5d3e-4d2c-be2f-6fd48e08706b' and summary = $dari${"en":"A booking and operations platform for intercity bus companies: passengers search trips and pick seats on a live seat map, while operators manage routes, buses, drivers and trips from a database-backed admin.","fa":"پلتفرم رزرو و مدیریت عملیات برای شرکت‌های اتوبوس‌رانی بین‌شهری است. مسافران سفر را جست‌وجو و صندلی را روی نقشه‌ی زنده انتخاب می‌کنند؛ اپراتورها هم مسیرها، ناوگان، رانندگان و سفرها را از یک پنل متصل به پایگاه داده مدیریت می‌کنند."}$dari$::jsonb;
update public.projects set title = $dari${"en":"Transportation System","fa":"سیستم حمل‌ونقل"}$dari$::jsonb where id = '7ef73c47-5d3e-4d2c-be2f-6fd48e08706b' and title = $dari${"en":"Transportation System","fa":"سامانه‌ی حمل‌ونقل"}$dari$::jsonb;
update public.service_packages set for_whom = $dari${"en":"A stable, low-change product that mainly needs someone keeping dependencies and backups healthy.","fa":"یک محصول پایدار و کم‌تغییر که بیشتر به نگهداری وابسته‌گی‌ها و پشتیبان‌گیری نیاز دارد."}$dari$::jsonb where id = 'fa57ae08-85a0-4529-9697-2c94a982deb1' and for_whom = $dari${"en":"A stable, low-change product that mainly needs someone keeping dependencies and backups healthy.","fa":"یک محصول پایدار و کم‌تغییر که بیشتر به نگهداری وابستگی‌ها و پشتیبان‌گیری نیاز دارد."}$dari$::jsonb;
update public.service_packages set included = $dari$[{"en":"Dependency and security updates on a monthly cadence","fa":"به‌روزرسانی وابسته‌گی‌ها و امنیت با ریتم ماهانه"},{"en":"Error monitoring and a monthly health check","fa":"مانیتورینگ خطا و یک بررسی سلامت ماهانه"},{"en":"A monthly backups check","fa":"یک بررسی ماهانه‌ی پشتیبان‌گیری"}]$dari$::jsonb where id = 'fa57ae08-85a0-4529-9697-2c94a982deb1' and included = $dari$[{"en":"Dependency and security updates on a monthly cadence","fa":"به‌روزرسانی وابستگی‌ها و امنیت با ریتم ماهانه"},{"en":"Error monitoring and a monthly health check","fa":"مانیتورینگ خطا و یک بررسی سلامت ماهانه"},{"en":"A monthly backups check","fa":"یک بررسی ماهانه‌ی پشتیبان‌گیری"}]$dari$::jsonb;
update public.service_process_steps set description = $dari${"en":"A short audit of the current product, dependencies and backup setup before the plan starts.","fa":"یک ارزیابی کوتاه از محصول فعلی، وابسته‌گی‌ها و وضعیت پشتیبان‌گیری، پیش از شروع برنامه."}$dari$::jsonb where id = 'de45168e-cb9a-42bb-bc69-06ade63e04a5' and description = $dari${"en":"A short audit of the current product, dependencies and backup setup before the plan starts.","fa":"یک ارزیابی کوتاه از محصول فعلی، وابستگی‌ها و وضعیت پشتیبان‌گیری، پیش از شروع برنامه."}$dari$::jsonb;
update public.services set for_whom = $dari$[{"en":"A founder or business with a real product idea and unclear or evolving scope","fa":"یک بنیان‌گذار یا کسب‌وکار با طرح محصولی واقعی و محدوده‌ای که هنوز در حال شکل‌گیری است"},{"en":"A team that needs user accounts, a database and real business logic — not just informational pages","fa":"تیمی که به حساب کاربری، پایگاه داده و منطق واقعی کسب‌وکار نیاز دارد — نه فقط صفحات اطلاع‌رسانی"}]$dari$::jsonb where id = 'b521c980-0a1f-45ae-8323-0b6aefd2f98e' and for_whom = $dari$[{"en":"A founder or business with a real product idea and unclear or evolving scope","fa":"یک بنیان‌گذار یا کسب‌وکار با ایده‌ی محصولی واقعی و محدوده‌ای که هنوز در حال شکل‌گیری است"},{"en":"A team that needs user accounts, a database and real business logic — not just informational pages","fa":"تیمی که به حساب کاربری، پایگاه داده و منطق واقعی کسب‌وکار نیاز دارد — نه فقط صفحات اطلاع‌رسانی"}]$dari$::jsonb;
update public.services set requirements = $dari$[{"en":"Access to the existing codebase and any current database, if one exists","fa":"دسترسی به کدبیس موجود و هر پایگاه داده‌ی فعلی، اگر وجود دارد"},{"en":"Credentials or sandbox access for any third-party service that needs integrating","fa":"معلومات دسترسی یا sandbox هر سرویس شخص‌ثالثی که باید متصل شود"}]$dari$::jsonb where id = '252b993b-802b-4db5-b677-db3374badf31' and requirements = $dari$[{"en":"Access to the existing codebase and any current database, if one exists","fa":"دسترسی به کدبیس موجود و هر پایگاه داده‌ی فعلی، اگر وجود دارد"},{"en":"Credentials or sandbox access for any third-party service that needs integrating","fa":"اطلاعات دسترسی یا sandbox هر سرویس شخص‌ثالثی که باید متصل شود"}]$dari$::jsonb;
update public.services set for_whom = $dari$[{"en":"A live product that needs someone keeping an eye on it between larger pieces of work","fa":"یک محصول زنده که بین کارهای بزرگ‌تر، به کسی نیاز دارد که مراقبش باشد"},{"en":"An owner who wants dependency and security updates to actually happen, not just get postponed","fa":"صاحب محصولی که می‌خواهد به‌روزرسانی‌های وابسته‌گی و امنیت واقعاً انجام شوند، نه فقط به تعویق بیفتند"}]$dari$::jsonb where id = '4631489f-67cc-420a-bd8f-824822d0860a' and for_whom = $dari$[{"en":"A live product that needs someone keeping an eye on it between larger pieces of work","fa":"یک محصول زنده که بین کارهای بزرگ‌تر، به کسی نیاز دارد که مراقبش باشد"},{"en":"An owner who wants dependency and security updates to actually happen, not just get postponed","fa":"صاحب محصولی که می‌خواهد به‌روزرسانی‌های وابستگی و امنیت واقعاً انجام شوند، نه فقط به تعویق بیفتند"}]$dari$::jsonb;
update public.services set included = $dari$[{"en":"Dependency and security updates on a monthly cadence","fa":"به‌روزرسانی وابسته‌گی‌ها و امنیت با ریتم ماهانه"},{"en":"Error monitoring and a monthly health check","fa":"مانیتورینگ خطا و یک بررسی سلامت ماهانه"},{"en":"A pool of small-change time each month for minor fixes and content tweaks","fa":"مقداری زمان اختصاصی هر ماه برای اصلاح‌های جزئی و تغییرات کوچک محتوا"},{"en":"A monthly backups check — confirming a real backup exists and can be restored","fa":"یک بررسی ماهانه‌ی پشتیبان‌گیری — تأیید اینکه یک نسخه‌ی پشتیبان واقعی وجود دارد و قابل‌بازیابی است"}]$dari$::jsonb where id = '4631489f-67cc-420a-bd8f-824822d0860a' and included = $dari$[{"en":"Dependency and security updates on a monthly cadence","fa":"به‌روزرسانی وابستگی‌ها و امنیت با ریتم ماهانه"},{"en":"Error monitoring and a monthly health check","fa":"مانیتورینگ خطا و یک بررسی سلامت ماهانه"},{"en":"A pool of small-change time each month for minor fixes and content tweaks","fa":"مقداری زمان اختصاصی هر ماه برای اصلاح‌های جزئی و تغییرات کوچک محتوا"},{"en":"A monthly backups check — confirming a real backup exists and can be restored","fa":"یک بررسی ماهانه‌ی پشتیبان‌گیری — تأیید اینکه یک نسخه‌ی پشتیبان واقعی وجود دارد و قابل‌بازیابی است"}]$dari$::jsonb;
update public.services set problem = $dari${"en":"Products that ship and then get no attention accumulate outdated dependencies, unnoticed errors and small annoyances that compound. Someone needs to actually be looking, on a schedule, not only when something breaks loudly.","fa":"محصولی که بعد از راه‌اندازی رها شود، به‌مرور با وابسته‌گی‌های قدیمی و خطاهای دیده‌نشده روبه‌رو می‌شود. این خدمت برای بررسی منظم همین موارد است، نه فقط زمانی که چیزی خراب می‌شود."}$dari$::jsonb where id = '4631489f-67cc-420a-bd8f-824822d0860a' and problem = $dari${"en":"Products that ship and then get no attention accumulate outdated dependencies, unnoticed errors and small annoyances that compound. Someone needs to actually be looking, on a schedule, not only when something breaks loudly.","fa":"محصولی که بعد از راه‌اندازی رها شود، به‌مرور با وابستگی‌های قدیمی و خطاهای دیده‌نشده روبه‌رو می‌شود. این خدمت برای بررسی منظم همین موارد است، نه فقط زمانی که چیزی خراب می‌شود."}$dari$::jsonb;
update public.services set what_i_do = $dari$[{"en":"Apply dependency and security updates on a regular schedule","fa":"به‌روزرسانی وابسته‌گی‌ها و امنیت طبق یک برنامه‌ی منظم"},{"en":"Monitor for errors and confirm backups are actually running and restorable","fa":"پایش خطاها و بررسی اینکه پشتیبان‌گیری‌ها واقعاً اجرا می‌شوند و قابل‌بازیابی‌اند"},{"en":"Make the small changes that come up between larger engagements","fa":"انجام تغییرهای کوچکی که بین همکاری‌های بزرگ‌تر پیش می‌آیند"}]$dari$::jsonb where id = '4631489f-67cc-420a-bd8f-824822d0860a' and what_i_do = $dari$[{"en":"Apply dependency and security updates on a regular schedule","fa":"به‌روزرسانی وابستگی‌ها و امنیت طبق یک برنامه‌ی منظم"},{"en":"Monitor for errors and confirm backups are actually running and restorable","fa":"پایش خطاها و بررسی اینکه پشتیبان‌گیری‌ها واقعاً اجرا می‌شوند و قابل‌بازیابی‌اند"},{"en":"Make the small changes that come up between larger engagements","fa":"انجام تغییرهای کوچکی که بین همکاری‌های بزرگ‌تر پیش می‌آیند"}]$dari$::jsonb;
